(function ($) {
    $.fn.outerHtml = function () {
        return $("<p></p>").append(this.clone(true).show()).html()
    };
    $.fn.djDialog = function (options) {
        var _this = this;
        var content = $(this).outerHtml();
        var thisDialogId = 0;
        var init = function () {
            if ("close" == options) {
                thisDialogId = parseInt($("[contentId=" + _this.attr("id") + "]").attr("dialogId"));
                console.log(thisDialogId);
                colse()
            } else {
                _this.botton = options.botton || true;
                _this.width = options.width || 500;
                _this.title = options.title || "温馨提示";
                _this.ok = options.ok || {text: "确定", callBack: colse};
                _this.close = options.close || colse;
                _this.cancel = options.cancel || {text: "取消", callBack: colse};
                $(".fade").each(function () {
                    var dialogId = parseInt($(this).attr("dialogId"));
                    if (thisDialogId < dialogId) {
                        thisDialogId = dialogId
                    }
                });
                thisDialogId += ($(".fade").size());
                open()
            }
        };
        var open = function () {
            var button = "";
            if (_this.botton === true) {
                button += '<a class="popbotton1">' + _this.ok.text + "</a>";
                if (options.cancel) {
                    button += '<a class="popbotton2">' + _this.cancel.text + "</a>"
                }
            }
            var shade = '<div id="djFade_' + thisDialogId + '" dialogId="' + thisDialogId + '" class="fade" contentId="' + _this.attr("id") + '"></div>';
            var popUp = '<div id="djPopUp_' + thisDialogId + '" class="popUpCmwa"><div class="popBorder"></div><div class="popCont"><span class="popClose"></span><h2>' + _this.title + '</h2><div class="content">' + content + '</div><div class="buttonPop">' + button + "</div></div></div>";
            $("body").append(shade + popUp);
            $("#djFade_" + thisDialogId).css("opacity", 0.5).css("z-index", 9999 + thisDialogId);
            var $djPopUp = $("#djPopUp_" + thisDialogId);
            var popHeight = $djPopUp.outerHeight();
            $djPopUp.css({
                "width": _this.width,
                "margin-left": -(_this.width) / 2,
                "margin-top": -popHeight / 2,
                "z-index": 9999 + thisDialogId + 1
            });
            $djPopUp.find(".popClose").click(function () {
                _this.close()
            });
            $djPopUp.find(".popbotton1").click(function () {
                _this.ok.callBack()
            });
            $djPopUp.find(".popbotton2").click(function () {
                _this.cancel.callBack()
            });
            _this.remove()
        };
        var colse = function () {
            $("#djFade_" + thisDialogId).remove();
            $("#djPopUp_" + thisDialogId).remove();
            $("body").append($(content).hide())
        };
        init()
    }
})(jQuery);
if (!window.DJ) {
    window.DJ = {}
}
DJ.alert = function (message, title, callBack) {
    if ($("#djAlert").size() > 0) {
        return
    }
    var html = '<div id="djAlert" class="conIntext nobg">' + message + "</div>";
    $("body").append(html);
    $("#djAlert").djDialog({
        title: title || "温馨提示", ok: {
            text: "确定", callBack: function () {
                if (callBack) {
                    callBack()
                }
                $("#djAlert").djDialog("close");
                $("#djAlert").remove()
            }
        }, close: function () {
            $("#djAlert").djDialog("close");
            $("#djAlert").remove()
        }
    })
};
DJ.confirm = function (message, callBack, title) {
    if ($("#djConfirm").size() > 0) {
        return
    }
    var html = '<div id="djConfirm" class="conIntext nobg">' + message + "</div>";
    $("body").append(html);
    $("#djConfirm").djDialog({
        title: title || "温馨提示", ok: {
            text: "确定", callBack: function () {
                if (callBack) {
                    callBack(true)
                }
                $("#djConfirm").djDialog("close");
                $("#djConfirm").remove()
            }
        }, cancel: {
            text: "取消", callBack: function () {
                if (callBack) {
                    callBack(false)
                }
                $("#djConfirm").djDialog("close");
                $("#djConfirm").remove()
            }
        }, close: function () {
            $("#djConfirm").djDialog("close");
            $("#djConfirm").remove()
        }
    })
};
DJ.dialog = {
    success: function (message, callBack, title) {
        DJ.alert(message, callBack);
        $("#djAlert").addClass("rightBg")
    }, error: function (message, callBack, title) {
        DJ.alert(message, callBack);
        $("#djAlert").addClass("errorBg")
    }, warn: function (message, callBack, title) {
        DJ.alert(message, callBack);
        $("#djAlert").addClass("alertBg")
    }
};